            is IWindowsFormsEditorService editorService)
        {
            var control = CreateEditControl(value);

            // .NET 9 breaking change: DropDownControl no longer accepts null.
            // Guard against null before calling.
            if (control is not null)
            {
                editorService.DropDownControl(control);
                value = GetValueFromControl(control);
            }
        }
        return value;
    }

    private Control? CreateEditControl(object value) => new ListBox();
    private object GetValueFromControl(Control control) => ((ListBox)control).SelectedItem;
